class Solution:
    def bestLine(self, points: List[List[int]]) -> List[int]:
        best_count, best_i, best_j = 2, 0, 1
        n = len(points)
        for i in range(n):
            for j in range(i + 1, n):
                dx = points[j][0] - points[i][0]
                dy = points[j][1] - points[i][1]
                count = 2
                for k in range(n):
                    if k == i or k == j:
                        continue
                    ddx = points[k][0] - points[i][0]
                    ddy = points[k][1] - points[i][1]
                    if dx * ddy == dy * ddx:
                        count += 1
                if count > best_count:
                    best_count, best_i, best_j = count, i, j
        return [best_i, best_j]

impl Solution {
  pub fn best_line(points: Vec<Vec<i32>>) -> Vec<i32> {
    let n = points.len();
    let (mut best_count, mut best_i, mut best_j) = (2, 0usize, 1usize);
    for i in 0..n {
      for j in i + 1..n {
        let dx = (points[j][0] - points[i][0]) as i64;
        let dy = (points[j][1] - points[i][1]) as i64;
        let mut count = 2;
        for k in 0..n {
          if k == i || k == j {
            continue;
          }
          let ddx = (points[k][0] - points[i][0]) as i64;
          let ddy = (points[k][1] - points[i][1]) as i64;
          if dx * ddy == dy * ddx {
            count += 1;
          }
        }
        if count > best_count {
          best_count = count;
          best_i = i;
          best_j = j;
        }
      }
    }
    vec![best_i as i32, best_j as i32]
  }
}

